sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float h;
uniform float s;
uniform float v;
uniform float a;
float3 toHsv(float3 c) {
    float hi = max(c.r, max(c.g, c.b));
    float lo = min(c.r, min(c.g, c.b));
    float d = hi - lo;
    float hue = 0.0;
    if (d > 0.00001) {
        if (hi == c.r) hue = mod((c.g - c.b) / d, 6.0);
        else if (hi == c.g) hue = (c.b - c.r) / d + 2.0;
        else hue = (c.r - c.g) / d + 4.0;
    }
    return float3(hue / 6.0, hi > 0.0 ? d / hi : 0.0, hi);
}
float3 toRgb(float3 c) {
    float3 k = clamp(abs(mod(c.x * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    return c.z * mix(float3(1.0), k, c.y);
}
float pick(float k, float4 hsva, float luma) {
    if (k < 0.5) return hsva.x;
    if (k < 1.5) return hsva.y;
    if (k < 2.5) return hsva.z;
    if (k < 3.5) return hsva.w;
    if (k < 4.5) return luma;
    if (k < 5.5) return 0.0;
    return 1.0;
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float4 c = float4(src);
    if (c.a > 0.0) c.rgb /= c.a;
    float4 hsva = float4(toHsv(c.rgb), c.a);
    float luma = dot(c.rgb, float3(0.2126, 0.7152, 0.0722));
    float4 o = clamp(float4(pick(h, hsva, luma), pick(s, hsva, luma), pick(v, hsva, luma), pick(a, hsva, luma)), 0.0, 1.0);
    return half4(half3(toRgb(o.xyz)) * half(o.w), half(o.w));
}
